81: // Open builds a daemon from deps and its already-registered projects.
82: func Open(ctx context.Context, d Deps) (*Daemon, error) {
83: 	daemon := &Daemon{
84: 		deps:     d,
85: 		ctx:      ctx,
86: 		projects: make(map[string]*proj),
87: 	}
88: 	for _, rp := range d.Registry.List() {
89: 		var st State
90: 		err := d.Registry.LoadState(rp.Name, &st)
91: 		if err != nil {
92: 			if errors.Is(err, registry.ErrNoState) {
93: 				st = State{Loop: *supervisor.New(rp.Name, queue.Queue{})}
94: 			} else {
95: 				return nil, err
96: 			}
97: 		}
98: 		daemon.projects[rp.Name] = &proj{
99: 			reg:   rp,
100: 			state: st,
101: 			pumps: make(map[claude.Process]chan struct{}),
102: 		}
103: 	}
104: 	for _, name := range daemon.names() {
105: 		p := daemon.projects[name]
106: 		switch p.state.Loop.State {
107: 		case "running", "starting", "paused":
108: 			daemon.execute(ctx, name, p.state.Loop.Exited(-2, "", d.Now(), d.Config.Loop))
109: 		}
110: 	}
111: 	return daemon, nil
112: }
