408: 	defer d.mu.Unlock()
409: 	p, ok := d.projects[project]
410: 	if !ok {
411: 		return control.QueueView{}, control.ErrUnknownProject
412: 	}
413: 	if p.state.Loop.State != "idle" && p.state.Loop.State != "waiting" {
414: 		return control.QueueView{}, control.ErrBusy
415: 	}
416: 	q, err := queue.Load(plan, p.reg.Caps)
417: 	if err != nil {
418: 		return control.QueueView{}, fmt.Errorf("%w: %v", control.ErrBadInput, err)
419: 	}
420: 	p.state.Loop = *supervisor.New(project, q)
421: 	p.queuedAt = d.deps.Now()
422: 	if d.runningCount() < d.deps.Config.MaxParallel {
423: 		acts, berr := p.state.Loop.Begin(d.deps.Now())
424: 		if berr == nil {
425: 			d.execute(d.ctx, project, acts)
