595: // execute runs a batch of actions for project; d.mu must be held.
596: func (d *Daemon) execute(ctx context.Context, project string, acts []supervisor.Action) {
597: 	p := d.projects[project]
598: 	if p == nil {
599: 		return
600: 	}
601: 	defer func() {
602: 		_ = d.deps.Registry.SaveState(project, p.state)
603: 	}()
604: 	for _, act := range acts {
