672: 		return fail(err)
673: 	}
674: 	p.machine = session.New()
675: 	p.proc = proc
676: 	p.log = log
677: 	if startPump != nil {
678: 		startPump(d, ctx, project, proc, log)
679: 	}
680: 	return true
681: }
