116: // pumpExit records the process's exit in its own log and, when the process is
117: // still the project's current one, lets the loop decide what to do about it.
118: func (d *Daemon) pumpExit(ctx context.Context, project string, p claude.Process, l *eventlog.Log, st claude.ExitStatus) {
119: 	d.mu.Lock()
120: 	defer d.mu.Unlock()
121: 
122: 	pr := d.projects[project]
123: 	if pr == nil {
124: 		return
125: 	}
126: 	now := d.deps.Now()
127: 	payload, err := json.Marshal(struct {
128: 		Code   int    `json:"code"`
129: 		Stderr string `json:"stderr"`
130: 	}{Code: st.Code, Stderr: stderrTail(st.Stderr)})
131: 	if err == nil {
132: 		_, _ = l.Append("exit", json.RawMessage(payload), now)
133: 	}
134: 	if pr.proc != p {
135: 		return
136: 	}
137: 	pr.proc = nil
138: 	d.execute(ctx, project, pr.state.Loop.Exited(st.Code, st.Stderr, now, d.deps.Config.Loop))
139: }
