31: // ParseDotenv reads a .env document into a key-value map. Lines are trimmed;
32: // empty lines and lines beginning with "#" are skipped; an "export " prefix is
33: // removed; the first "=" splits key and value; the value is trimmed and, when
34: // wrapped in matching single or double quotes, unquoted.
35: func ParseDotenv(text string) map[string]string {
36: 	out := map[string]string{}
37: 	for _, line := range strings.Split(text, "\n") {
38: 		line = strings.TrimSpace(line)
39: 		if line == "" || strings.HasPrefix(line, "#") {
40: 			continue
41: 		}
42: 		line = strings.TrimPrefix(line, "export ")
43: 		idx := strings.Index(line, "=")
44: 		if idx < 0 {
45: 			continue
46: 		}
47: 		key := strings.TrimSpace(line[:idx])
48: 		val := strings.TrimSpace(line[idx+1:])
49: 		if len(val) >= 2 {
50: 			first, last := val[0], val[len(val)-1]
