174: // UUIDv4 renders a version 4 UUID from the given 16 bytes: the version nibble
175: // is forced in byte 6, the variant bits in byte 8, everything else is
176: // preserved. The result is lower-case hex in the groups 8-4-4-4-12.
177: func UUIDv4(b [16]byte) string {
178: 	b[6] = 0x40 | (b[6] & 0x0f)
179: 	b[8] = 0x80 | (b[8] & 0x3f)
180: 
181: 	const hex = "0123456789abcdef"
182: 	out := make([]byte, 0, 36)
183: 	for i := 0; i < 16; i++ {
184: 		if i == 4 || i == 6 || i == 8 || i == 10 {
185: 			out = append(out, '-')
186: 		}
187: 		out = append(out, hex[b[i]>>4], hex[b[i]&0x0f])
188: 	}
189: 	return string(out)
190: }

